+
+template <typename T>
+__device__ __forceinline__ T relu2_no_mul_kernel(const T& x) {
+  const float value = fmaxf((float)x, 0.0f);
+  return (T)(value * value);
+}
+
+template <typename scalar_t, scalar_t (*ACT_FN)(const scalar_t&),
