+                                             first_row, end_row, row_stride)) {
+    return;
+  }
+
+  for (int64_t row = first_row; row < end_row; row += row_stride) {
+    const int64_t offset = row * d + idx;
+    out[offset] = ACT_FN(VLLM_LDG(&input[offset]));
+  }
+}
